import "server-only"
import { mkdir, readFile, writeFile, access } from "node:fs/promises"
import path from "node:path"

/**
 * Minimal file storage for original template files. Keys are generated by the server
 * (never taken from user input) and resolved inside STORAGE_DIR. In production this module
 * is the single place to swap for S3 / Vercel Blob.
 */
function root() {
  if (process.env.STORAGE_DIR) return process.env.STORAGE_DIR
  return process.env.VERCEL ? "/tmp/presentation-templates-storage" : path.join(process.cwd(), "data", "storage")
}

function resolveKey(key: string) {
  if (!/^[a-z0-9/_.-]+$/i.test(key) || key.includes("..")) throw new Error(`Invalid storage key: ${key}`)
  return path.join(root(), key)
}

export async function putFile(key: string, data: Buffer | Uint8Array) {
  const file = resolveKey(key)
  await mkdir(path.dirname(file), { recursive: true })
  await writeFile(file, data)
  return key
}

export async function getFile(key: string): Promise<Buffer | null> {
  try {
    return await readFile(resolveKey(key))
  } catch {
    return null
  }
}

export async function fileExists(key: string) {
  try {
    await access(resolveKey(key))
    return true
  } catch {
    return false
  }
}
